/* TikTok Quote — extracted from index.html v3. Classic script; keep execution order. */

/* ===== original script 3: nxTikTokQuoteEmbeddedApp ===== */
(function(){
  'use strict';
  var TTQUOTE_APP_B64 = '';

  function decodeUtf8Base64(value){
    var binary = atob(value);
    var bytes = new Uint8Array(binary.length);
    for(var i=0;i<binary.length;i++) bytes[i] = binary.charCodeAt(i);
    if(typeof TextDecoder !== 'undefined'){
      return new TextDecoder('utf-8').decode(bytes);
    }
    var encoded = '';
    for(var j=0;j<bytes.length;j++) encoded += '%' + bytes[j].toString(16).padStart(2,'0');
    return decodeURIComponent(encoded);
  }

  /* Override renderer lama tanpa menghapus kode/fallback aslinya. */
  window.renderTiktokQuote = function(body){
    body.innerHTML =
      '<div class="nx-ttquote-embed">' +
        '<div class="nx-ttquote-loading" id="nxTtQuoteLoading">Loading Quote Chat</div>' +
        '<iframe class="nx-ttquote-frame" id="nxTtQuoteFrame" title="Nexora TikTok Quote Chat" sandbox="allow-scripts allow-forms allow-popups allow-modals allow-downloads" allow="clipboard-write" referrerpolicy="no-referrer" loading="eager"></iframe>' +
      '</div>';

    var frame = document.getElementById('nxTtQuoteFrame');
    var loading = document.getElementById('nxTtQuoteLoading');
    if(!frame) return;

    frame.addEventListener('load',function(){
      if(loading) loading.classList.add('is-hidden');
    },{once:true});

    try{
      frame.srcdoc = decodeUtf8Base64(TTQUOTE_APP_B64);
    }catch(err){
      if(loading){
        loading.textContent = 'Aplikasi gagal dimuat';
        loading.style.color = '#fb7185';
      }
      console.error('[TikTok Quote Nexora]',err);
    }
  };
})();

/* ===== original script 4: nxTikTokQuoteBackDirectFix ===== */
(function(){
  'use strict';

  function isTikTokQuoteOpen(){
    var room = document.getElementById('nxUniversalRoom');
    return !!(room &&
      room.classList.contains('is-open') &&
      room.getAttribute('data-tool') === 'ttquote');
  }

  function closeTikTokQuoteDirect(event){
    if(event){
      event.preventDefault();
      event.stopPropagation();
      if(typeof event.stopImmediatePropagation === 'function'){
        event.stopImmediatePropagation();
      }
    }

    var room = document.getElementById('nxUniversalRoom');
    if(!room || room.getAttribute('data-tool') !== 'ttquote') return false;

    /* Tutup visual dan iframe langsung agar tombol selalu merespons. */
    room.classList.remove('is-visible', 'is-open');
    room.style.display = 'none';
    room.setAttribute('aria-hidden', 'true');

    var body = document.getElementById('nxUniversalRoomBody');
    if(body) body.innerHTML = '';

    document.body.classList.remove('nx-universal-room-open');
    document.body.style.overflow = 'auto';

    /* Rapikan history setelah ruang sudah pasti tertutup. */
    if(history.state && history.state.nxUniversalTool === 'ttquote'){
      try{
        history.back();
      }catch(err){
        try{
          history.replaceState(null, '', location.href.split('#')[0]);
        }catch(ignore){}
      }
    }else if(location.hash.indexOf('#tool-ttquote') === 0){
      try{
        history.replaceState(null, '', location.href.split('#')[0]);
      }catch(ignore){}
    }
    return true;
  }

  function bindBackButton(){
    var button = document.getElementById('nxUniversalRoomBack');
    if(!button || button.dataset.ttquoteDirectBack === '1') return;
    button.dataset.ttquoteDirectBack = '1';

    /* Capture=true membuat tambalan berjalan sebelum handler lama. */
    button.addEventListener('click', function(event){
      if(isTikTokQuoteOpen()) closeTikTokQuoteDirect(event);
    }, true);
  }

  document.addEventListener('click', function(event){
    var button = event.target && event.target.closest
      ? event.target.closest('#nxUniversalRoomBack')
      : null;
    if(button && isTikTokQuoteOpen()){
      closeTikTokQuoteDirect(event);
    }
  }, true);

  document.addEventListener('keydown', function(event){
    if(event.key === 'Escape' && isTikTokQuoteOpen()){
      closeTikTokQuoteDirect(event);
    }
  }, true);

  var observer = new MutationObserver(bindBackButton);
  observer.observe(document.documentElement, {childList:true, subtree:true});
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', bindBackButton);
  }else{
    bindBackButton();
  }

  window.closeTikTokQuoteNexora = closeTikTokQuoteDirect;
})();
